import sys

def solve() -> None:
    data = sys.stdin.read().strip()
    if not data:
        return
    Y = int(data)
    # Leap year rules for Gregorian calendar
    if (Y % 400 == 0) or (Y % 4 == 0 and Y % 100 != 0):
        print(366)
    else:
        print(365)

if __name__ == "__main__":
    solve()
