import sys

def solve() -> None:
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        return
    S, T = data[0].strip(), data[1].strip()
    n, m = len(S), len(T)
    min_len = min(n, m)

    # Find first differing position within the overlapping part
    for i in range(min_len):
        if S[i] != T[i]:
            print(i + 1)          # 1-indexed position
            return

    # No difference in the overlapping part
    if n == m:
        print(0)
    else:
        # The first differing position is just after the shorter string
        print(min_len + 1)

if __name__ == "__main__":
    solve()
```

